let gl, _gl;

let attrBuf;

let myShader;
let vs =
"precision mediump float;" +
"attribute vec4 aMyAttr;" + // いけるか？？
"uniform float uCount;" +
"const float TAU = 6.28318;" +
"varying float vStrokeWeight;" +
"varying float vColorValue;" +
"varying vec3 vParam;" +
"uniform mat4 uModelViewMatrix;" +
"uniform mat4 uProjectionMatrix;" +
"const float s = 10.0;" +
// メインコード
"void main() {" +
"  float _sign = aMyAttr.x;" + // 符号
"  float y = aMyAttr.y;" + // y,x,iはそのまま使えるようにする
"  float x = aMyAttr.z;" +
"  float i = aMyAttr.w;" +
"  vParam = vec3(y,x,i);" +
"  vColorValue = min(min(555.0 - y * 3.0, i + 400.0), 300.0 - abs(x)) / 255.0;" +
"  vec3 p;" +
"  p.x = x + sin(i + uCount) * s;" +
"  p.y = y * 0.5 * _sign;" +
"  p.z = i + cos(i + uCount) * s;" +
"  vec4 positionVec4 =  vec4(p, 1.0);" +
"  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;" +
"  gl_PointSize = 5.0;" +
"  vStrokeWeight = 5.0;" +
"}";

let fs =
"precision mediump float;" +
"precision mediump int;" +
"uniform vec4 uMaterialColor;" +
"uniform float uCount;" +
"const float TAU = 6.28318;" +
"varying float vStrokeWeight;" +
"varying float vColorValue;" +
"varying vec3 vParam;" +
// getRGB(HSBtoRGB)
"vec3 getRGB(float h, float s, float b){" +
"    vec3 c = vec3(h, s, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +

"void main(){" +
"  float mask = 0.0;" +
"  if(vParam.x < 100.0){discard;}" + // なぜか知らないけどこれでうまくいく
"  mask = step(0.98, length(gl_PointCoord * 2.0 - 1.0));" +
"  mask = mix(0.0, mask, clamp(floor(vStrokeWeight - 0.5),0.0,1.0));" +
"  if(mask > 0.98){ discard; }" +
"  float d = (vParam.x - 100.0) / 200.0;" +
"  gl_FragColor = vec4(getRGB(0.53 + 0.2 * d , 0.5 + d, vColorValue), 1.0);" +
"}";

let properFrameCount = 0;
let NUM = 0;

function setup(){
  _gl=createCanvas(w=1112, h=834, WEBGL);
  gl = _gl.GL
  pixelDensity(1);
  myShader = createShader(vs, fs);

  attrBuf = gl.createBuffer(); // はい水増し
  // 要するにこれがvboなんだそうです（最重要情報）
  // ここでバッファ関連の処理
  let attrs = [];
  for(let _sign = -1; _sign < 2; _sign += 2){
    for(let y = 100; y < 350; y += 6){
      for(let x = -w/2; x <= w/2; x += 50){
        for(let i = -h/2; i < h/2; i += 6){
          attrs.push(_sign, y, x, i);
        }
      }
    }
  }
  NUM = attrs.length / 4;
  // 登録は1回だけ。これで高速化できる。
  gl.bindBuffer(gl.ARRAY_BUFFER, attrBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(attrs), gl.STATIC_DRAW);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
}

function draw(){
  background(0);
  shader(myShader);
  myShader.setUniform("uCount", properFrameCount * 0.1);
  myDrawPoints();
  properFrameCount++;
}

function myDrawPoints(){
  _gl._setPointUniforms(myShader);

  gl.bindBuffer(gl.ARRAY_BUFFER, attrBuf);
  myShader.enableAttrib(myShader.attributes.aMyAttr, 4);

  gl.drawArrays(gl.Points, 0, NUM);
  myShader.unbindShader();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

